                            Particle *n = &particles[index];
                            float distSq = glm::length2(p->position - n->position);
                            if (distSq <= h2) {
                                density += mass * poly6 * pow(h2 - distSq, 3);
                            }
                            index++;
                        }
                    }
                }
            }
        }

        p->density = density + selfDens;
        p->pressure = gasConstant * (p->density - restDensity);
    }
